using Dicom;
using Dicom.Network;
using System;
using System.Collections.Generic;
using System.IO;
using System.IO.Abstractions.TestingHelpers;
using xRetry;
using Xunit;

namespace Nvidia.Clara.DicomAdapter.API.Test
{
    public class InstanceStorageInfoTest
    {
        private DicomDataset _dataset;
        private DicomCStoreRequest _request;
        private MockFileSystem _fileSystem;
        private string _storageRoot;
        private string _studyInstanceUid;
        private string _seriesInstanceUid;
        private string _sopInstanceUid;

        public InstanceStorageInfoTest()
        {
            _studyInstanceUid = DicomUIDGenerator.GenerateDerivedFromUUID().UID;
            _seriesInstanceUid = DicomUIDGenerator.GenerateDerivedFromUUID().UID;
            _sopInstanceUid = DicomUIDGenerator.GenerateDerivedFromUUID().UID;
            _storageRoot = Path.DirectorySeparatorChar + "clara";
            _dataset = new DicomDataset
            {
                { DicomTag.SOPClassUID, "1.2.3" },
                { DicomTag.PatientID, "PID" },
                { DicomTag.StudyInstanceUID, _studyInstanceUid },
                { DicomTag.SeriesInstanceUID, _seriesInstanceUid },
                { DicomTag.SOPInstanceUID, _sopInstanceUid }
            };
            var file = new DicomFile(_dataset);
            _request = new DicomCStoreRequest(file);
            _fileSystem = new MockFileSystem(new Dictionary<string, MockFileData>
            {
                {_storageRoot, new MockDirectoryData() }
            });
        }

        [RetryFact(DisplayName = "Create with null DicomCStoreRequest shall throw exception")]
        public void CreateWithNullDicomCStoreRequestShallThrow()
        {
            Assert.Throws<ArgumentNullException>(() =>
            {
                InstanceStorageInfo.CreateInstanceStorageInfo(
                    null,
                    _storageRoot,
                    "AETITLE",
                    1);
            });
        }

        [RetryFact(DisplayName = "Create without storageRootFullPath shall throw exception")]
        public void CreateWithoutStorageRootFullPathShallThrow()
        {
            Assert.Throws<ArgumentException>(() =>
            {
                InstanceStorageInfo.CreateInstanceStorageInfo(
                    _request,
                    string.Empty,
                    "AETITLE",
                    1);
            });
        }

        [RetryFact(DisplayName = "Create without sourceAeTitle shall throw exception")]
        public void CreateWithoutSourceAeTitleShallThrow()
        {
            Assert.Throws<ArgumentException>(() =>
            {
                InstanceStorageInfo.CreateInstanceStorageInfo(
                    _request,
                    _storageRoot,
                    " ",
                    1);
            });
        }

        [RetryFact(DisplayName = "Create a valid instance of InstanceStorageInfo")]
        public void CreateWithValidData()
        {
            var expectedAeStoragePath = Path.Combine(_storageRoot, "MyAeTitle");
            var expectedAeAssocationStoragePath = Path.Combine(expectedAeStoragePath, "1", "dcm");
            var expectedPatientStoragePath = Path.Combine(expectedAeAssocationStoragePath, "PID");
            var expectedSeriesStoragePath = Path.Combine(expectedPatientStoragePath, Path.Combine(_studyInstanceUid, _seriesInstanceUid));
            var expectedInstanceStoragePath = Path.Combine(expectedSeriesStoragePath, $"{_sopInstanceUid}.dcm");

            var instance = InstanceStorageInfo.CreateInstanceStorageInfo(
                _request,
                expectedAeStoragePath,
                "MyAeTitle",
                1,
                _fileSystem);

            Assert.Equal("1.2.3", instance.SopClassUid);
            Assert.Equal("PID", instance.PatientId);
            Assert.Equal(_studyInstanceUid, instance.StudyInstanceUid);
            Assert.Equal(_seriesInstanceUid, instance.SeriesInstanceUid);
            Assert.Equal(_sopInstanceUid, instance.SopInstanceUid);
            Assert.Equal("MyAeTitle", instance.CalledAeTitle);
            Assert.Equal(expectedAeAssocationStoragePath, instance.AeStoragePath);
            Assert.Equal(expectedPatientStoragePath, instance.PatientStoragePath);
            Assert.Equal(expectedInstanceStoragePath, instance.InstanceStorageFullPath);

            Assert.True(_fileSystem.Directory.Exists(expectedSeriesStoragePath));
        }
    }
}

# Job Processors

A *Job Processor* allows the user to configure how received DICOM instances will be associated with
one or more configured Clara pipelines. Each configured Clara SCP AE Title must have one `processor`
configured; if omitted, the default *AE Title Job Processor* is used.

## Extending JobProcessorBase

By extending `JobProcessorBase`, which is found in `Nvidia.Clara.Dicom.API.dll`, developers can
customize their inference job submission workflow.

The following code snippet contains the properties and methods that are required
when implementing a Job Processor:

```csharp
public abstract class JobProcessorBase : IDisposable, IObserver<InstanceStorageInfo>
{
    public abstract string Name { get; }
    public abstract string AeTitle { get; }
    public abstract void HandleInstance(InstanceStorageInfo value);

}
```

* `Name`: The name for the job processor.
* `AeTitle`: The AE Title that the processor is attached to.
* `HandleInstance(...)`: A detailed implementation of how a job processor handles received
  instances. 

To submit a job in the `HandleInstance(...)` method, developers can simply call
`base.SubmitPipelineJob(...)`, giving the name of the job, the pipeline ID that has been registered
with Clara Platform, the priority, and the DICOM instances to be associated with the job.

Once job submission is completed, `RemoveInstances(...)` should be called with the instances so
the DICOM files in the temporary storage can be cleaned up by the *Storage Space Reclaimer Service*.

### Sample Snippet

```csharp
[ProcessorValidation(ValidatorType = typeof(CustomJobProcessorValidator))]
public class MyJobProcessor : JobProcessorBase
{
    public override string Name => "My Custom Job Processor";
    public override string AeTitle => _configuration.AeTitle;

    public override void HandleInstance(InstanceStorageInfo value)
    {
        if (value is null)
        {
            throw new ArgumentNullException(nameof(value));
        };
        if (!value.CalledAeTitle.Equals(_configuration.AeTitle))
        {
            throw new InstanceNotSupportedException(value);
        };

        // handle the instance here
    }

    protected override void Dispose(bool disposing)
    {
        // dispose any resource if needed
    }
}


public class CustomJobProcessorValidator : IJobProcessorValidator
{

    public void Validate(string aeTitle, Dictionary<string, string> processorSettings)
    {
        // validate all processor settings
        // throw if anything is invalid
        // optionally throw on keys/values that are not used
    }
}
```

The `ProcessorValidation` attribute must be decorated for each derived class of `JobProcessorBase`, 
and a job processor validator must be provided. The validator must implement the
`IJobProcessorValidator` inteface and validate any processor settings passed into the Clara
Create AE Title API call, including the CLI.

